export const LEVELS: Level[] = [
  { level: 1, name: "Booting Up", minXp: 0, maxXp: 500 },
  { level: 2, name: "Kernel Loading", minXp: 500, maxXp: 1400 },
  { level: 3, name: "Packet Sniffer", minXp: 1400, maxXp: 2500 },
  { level: 4, name: "System Debugger", minXp: 2500, maxXp: 3800 },
  { level: 5, name: "Protocol Admin", minXp: 3800, maxXp: 5200 },
  { level: 6, name: "Systems Architect", minXp: 5200, maxXp: 6800 },
  { level: 7, name: "Zero Lag", minXp: 6800, maxXp: ROOT_ACCESS_XP },
  { level: 8, name: "Root Access", minXp: ROOT_ACCESS_XP, maxXp: ROOT_ACCESS_XP },
];

export function getLevelForXP(xp: number): Level {
  return [...LEVELS].reverse().find((level) => xp >= level.minXp) ?? LEVELS[0];
}

export function getChaptersForPart(part: number): Chapter[] {
  return CHAPTERS.filter((chapter) => chapter.part === part).sort((a, b) => a.order - b.order);
}
